// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * A packed-planner deadline is an absolute {@link System#nanoTime()} value; the JDK clock may have a negative origin,
 * so a deadline at or below zero is a real deadline and only {@link Long#MAX_VALUE} means "no deadline".
 */
class PackedPlannerDeadlineTest {

	@Test
	void negativeAbsoluteDeadlineIsKeptByTheLimits() {
		assertEquals(-5L, new PackedPlannerLimits(10L, -5L).deadlineNanos(),
				"a negative nanoTime deadline must not become 'no deadline'");
		assertEquals(0L, new PackedPlannerLimits(10L, 0L).deadlineNanos());
		assertEquals(Long.MAX_VALUE, new PackedPlannerLimits(10L, Long.MAX_VALUE).deadlineNanos());
	}

	@Test
	void expiredNegativeDeadlineStopsOptionalWork() {
		PackedSearchBudget budget = new PackedSearchBudget(1_000L, Long.MIN_VALUE + 1L);

		assertFalse(budget.tryReserve(1L), "a deadline in the past must refuse optional work");
		assertTrue(budget.deadlineReached());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, budget.completionStatus());
		assertEquals(0L, budget.workUnits());
	}

	@Test
	void unboundedLimitsNeverReachTheDeadline() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());

		assertTrue(budget.tryReserve(1L));
		assertTrue(budget.sampleDeadline());
		assertFalse(budget.deadlineReached());
	}
}
